create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'admin' check(role in('admin','editor')),created_at timestamptz default now());
create table if not exists public.funds(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,icon text default 'wallet',sort_order int default 0,created_at timestamptz default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),fund_id uuid not null references public.funds(id),type text not null check(type in('income','expense')),amount numeric(14,2) not null check(amount>0),transaction_date date not null default current_date,description text not null,is_published boolean default true,voided_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.activities(id uuid primary key default gen_random_uuid(),title text not null,category text,description text,event_date timestamptz,cover_url text,is_published boolean default false,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.pages(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,content text,is_published boolean default false,sort_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.site_settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_at timestamptz default now());
create or replace view public.fund_balances as select f.code,f.name,f.icon,f.sort_order,coalesce(sum(case when t.type='income' then t.amount when t.type='expense' then -t.amount else 0 end),0)::numeric as balance from public.funds f left join public.transactions t on t.fund_id=f.id and t.voided_at is null and t.is_published=true group by f.id;
insert into public.funds(code,name,icon,sort_order) values('yatim','Kas Anak Yatim','heart',1),('operasional','Kas Operasional','wallet',2),('pembangunan','Kas Pembangunan','building',3),('qurban','Nabung Qurban','moon',4) on conflict(code) do nothing;
alter table public.profiles enable row level security;alter table public.funds enable row level security;alter table public.transactions enable row level security;alter table public.activities enable row level security;alter table public.pages enable row level security;alter table public.site_settings enable row level security;
create policy "public read funds" on public.funds for select using(true);create policy "public read published transactions" on public.transactions for select using(is_published=true and voided_at is null);create policy "public read activities" on public.activities for select using(is_published=true);create policy "public read pages" on public.pages for select using(is_published=true);create policy "public read settings" on public.site_settings for select using(true);
create policy "admins manage funds" on public.funds for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','editor'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','editor')));create policy "admins manage transactions" on public.transactions for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','editor'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','editor')));create policy "admins manage activities" on public.activities for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','editor'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','editor')));
